import { normalizeSpeech, segmentKey, speechSegments } from '../game/speech-lines'
import type { Audio } from './audio'

type Manifest = { voice: string; clips: string[] }
declare global {
  interface Window { __speechLog?: { text: string; lang: string; rate: number; source?: string }[] }
}

/**
 * Narration player. Uses the pre-recorded voice clips in `public/voice/` (generated by
 * `scripts/generate-voice.mjs`) when every sentence of a line has a clip; otherwise it falls
 * back to the browser's zh-TW speech synthesis so nothing goes silent.
 */
export class Voice {
  private static readonly shared = new WeakMap<Audio, Voice>()
  private clips: Set<string> | null = null
  private manifestRequest: Promise<void> | null = null
  private readonly gain: GainNode
  private playing: AudioBufferSourceNode[] = []
  private token = 0

  /** One narrator per audio engine, shared by the campaign and free-practice screens. */
  static for(audio: Audio): Voice {
    let voice = Voice.shared.get(audio)
    if (!voice) {
      voice = new Voice(audio)
      Voice.shared.set(audio, voice)
    }
    return voice
  }

  private constructor(private readonly audio: Audio) {
    this.gain = audio.ctx.createGain()
    this.gain.gain.value = 1
    this.gain.connect(audio.ctx.destination)
    void this.loadManifest()
  }

  private loadManifest(): Promise<void> {
    this.manifestRequest ??= fetch(`${import.meta.env.BASE_URL}voice/manifest.json`)
      .then(response => (response.ok ? response.json() as Promise<Manifest> : null))
      .then(manifest => { this.clips = new Set(manifest?.clips ?? []) })
      .catch(() => { this.clips = new Set() })
    return this.manifestRequest
  }

  get recordedClipCount(): number {
    return this.clips?.size ?? 0
  }

  cancel(): void {
    this.token += 1
    for (const source of this.playing) {
      try { source.stop() } catch { /* already stopped */ }
    }
    this.playing = []
    this.audio.duck(false)
    try { window.speechSynthesis?.cancel() } catch { /* unsupported */ }
  }

  /** Reads `text` aloud; returns false only when no voice output is possible at all. */
  speak(text: string, rate: number): boolean {
    this.cancel()
    const segments = speechSegments(text)
    if (segments.length === 0) return true
    if (this.clips && this.clips.size > 0 && segments.every(segment => this.clips?.has(segmentKey(segment)))) {
      window.__speechLog?.push({ text: normalizeSpeech(text), lang: 'zh-TW', rate, source: 'recorded' })
      void this.playClips(segments.map(segmentKey), this.token)
      return true
    }
    return this.synthesize(text, rate)
  }

  private async playClips(keys: string[], token: number): Promise<void> {
    this.audio.unlock()
    this.audio.duck(true)
    try {
      const buffers = await Promise.all(keys.map(key => this.audio.load(`${import.meta.env.BASE_URL}voice/${key}.mp3`)))
      if (token !== this.token) return
      let at = this.audio.ctx.currentTime + 0.03
      for (const buffer of buffers) {
        const source = this.audio.ctx.createBufferSource()
        source.buffer = buffer
        source.connect(this.gain)
        source.start(at)
        this.playing.push(source)
        at += buffer.duration + 0.12
      }
      const last = this.playing[this.playing.length - 1]
      if (last) last.onended = () => { if (token === this.token) this.audio.duck(false) }
    } catch {
      if (token === this.token) this.audio.duck(false)
    }
  }

  private synthesize(text: string, rate: number): boolean {
    if (typeof window === 'undefined' || !('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined') return false
    const utterance = new SpeechSynthesisUtterance(normalizeSpeech(text))
    utterance.lang = 'zh-TW'
    utterance.rate = rate
    utterance.pitch = 1.02
    utterance.volume = 1
    window.speechSynthesis.speak(utterance)
    return true
  }
}
